export function byRole(role: string): readonly Contract[] {
  return CONTRACTS.filter((contract) => contract.roles.includes(role));
}

/** The lowercase addresses carrying role, in registry order. */
export function lowerByRole(role: string): readonly string[] {
  return byRole(role).map((contract) => contract.lower);
}
